with a as(select * from public.authors where open_library_id=any(array['OL2675573A']::text[])),w as(select * from public.works where open_library_id=any(array['OL19552275W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9781984819192','9789000365043']::text[]) or open_library_edition_id=any(array['OL26967814M','OL46531174M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987163001 and 987163999),'editions',(select count(*) from public.editions where id between 987263001 and 987263999),'authors',(select count(*) from public.authors where id between 987363001 and 987363999))) as preflight;
